/**
 * @brief 验证 0x19 耗材控制动作边界：action=0/1/2 返回 ACK，slot_id=4 或 action=3 返回 NACK 0x03 (ISS-20261105-010)
 */
static void verify_filament_action_and_slot_bounds(void)
{
    for (uint8_t act = 0U; act <= 2U; ++act)
    {
        const minimc_filament_req_t ok_req = { 0U, act, 10U };
        send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_SLOT_SELECT, (const uint8_t *)&ok_req, sizeof(ok_req));
        assert(s_last_ap_tx_frame[5] == MINIMC_CMD_SLOT_SELECT);
    }
    const minimc_filament_req_t bad_slot_req = { 4U, 0U, 0U };
    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_SLOT_SELECT, (const uint8_t *)&bad_slot_req, sizeof(bad_slot_req));
    assert(s_last_ap_tx_frame[5] == MINIMC_CMD_NACK);
    assert(s_last_ap_tx_frame[12] == 0x03U);

    const minimc_filament_req_t bad_action_req = { 0U, 3U, 0U };
    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_SLOT_SELECT, (const uint8_t *)&bad_action_req, sizeof(bad_action_req));
    assert(s_last_ap_tx_frame[5] == MINIMC_CMD_NACK);
    assert(s_last_ap_tx_frame[12] == 0x03U);
}

/**
 * @brief 验证 TWIN-60 热床真实 ADC 透传、5~130°C/ADC 越界故障哨兵、0x19 越界 NACK 0x03 及动态 boot_id（ISS-010/011/012/016）
 */
static void test_twin60_adc_range_filament_nack_and_boot_id(void)
{
    printf("[RUN ] test_twin60_adc_range_filament_nack_and_boot_id\n");
    current_temperature_ex1 = 210;
    current_temperature_bed = 60;
    g_last_bed_adc_raw = 2850U;
    minimc_proto_init();
    s_test_seq = 400U;

    /* 1. ISS-016: 连续两次复位/初始化生成的 boot_id 均非零且互不相同 */
    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_GET_VERSION, NULL, 0U);
    const uint32_t boot_id_1 = (uint32_t)s_last_ap_tx_frame[16] |
                               ((uint32_t)s_last_ap_tx_frame[17] << 8U) |
                               ((uint32_t)s_last_ap_tx_frame[18] << 16U) |
                               ((uint32_t)s_last_ap_tx_frame[19] << 24U);
    minimc_proto_init();
    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_GET_VERSION, NULL, 0U);
    const uint32_t boot_id_2 = (uint32_t)s_last_ap_tx_frame[16] |
                               ((uint32_t)s_last_ap_tx_frame[17] << 8U) |
                               ((uint32_t)s_last_ap_tx_frame[18] << 16U) |
                               ((uint32_t)s_last_ap_tx_frame[19] << 24U);
    assert((boot_id_1 != 0U) && (boot_id_2 != 0U) && (boot_id_1 != boot_id_2));

    /* 2. ISS-012: 正常温度下 0x14 报告透传真实 g_last_bed_adc_raw (2850U) */
    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_GET_TEMP, NULL, 0U);
    minimc_temp_report_payload_t pay;
    memcpy(&pay, &s_last_ap_tx_frame[12], sizeof(pay));
    assert(pay.current_temp_deci_c == 600);
    assert(pay.raw_adc_value == 2850U);
    assert(pay.sensor_status == MINIMC_TEMP_STATUS_OK);

    /* 3. ISS-011: 热床超量程 (>130°C 或 ADC > 4081 / < 70) 打入 0x7FFF 哨兵与开路/短路状态 */
    current_temperature_bed = 135;
    g_last_bed_adc_raw = 4090U;
    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_GET_TEMP, NULL, 0U);
    memcpy(&pay, &s_last_ap_tx_frame[12], sizeof(pay));
    assert(pay.current_temp_deci_c == MINIMC_TEMP_SENTINEL_FAULT);
    assert(pay.raw_adc_value == 4090U);
    assert(pay.sensor_status == MINIMC_TEMP_STATUS_DISCONNECTED);

    current_temperature_bed = 25;
    g_last_bed_adc_raw = 30U;
    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_GET_TEMP, NULL, 0U);
    memcpy(&pay, &s_last_ap_tx_frame[12], sizeof(pay));
    assert(pay.current_temp_deci_c == MINIMC_TEMP_SENTINEL_FAULT);
    assert(pay.sensor_status == MINIMC_TEMP_STATUS_SHORT);
    g_last_bed_adc_raw = 3200U;

    /* 4. ISS-010(MC): 验证 0x19 槽位与动作边界 (action=0..2 合法，action=3/slot=4 返回 NACK 0x03) */
    verify_filament_action_and_slot_bounds();
    printf("[PASS] test_twin60_adc_range_filament_nack_and_boot_id\n");
}

